rescale   0.5;

xMin   -40;
xMax    80;
yMin   -22;
yMax    22;
zMin    -0.3176;
zMax    19.6824;
xCells  #eval "120*$rescale";
yCells  #eval "44*$rescale";
zCells  #eval "20*$rescale";

vertices
(
    ($xMin $yMin $zMin)
    ($xMax $yMin $zMin)
    ($xMax $yMax $zMin)
    ($xMin $yMax $zMin)

    ($xMin $yMin $zMax)
    ($xMax $yMin $zMax)
    ($xMax $yMax $zMax)
    ($xMin $yMax $zMax)
);

blocks
(
    hex (0 1 2 3 4 5 6 7) ($xCells $yCells $zCells) simpleGrading (1 1 1)
);

edges
(
);

boundary
(
    inlet
    {
        type patch;
        faces
        (
            (0 3 7 4)
        );
    }
    outlet
    {
        type patch;
        faces
        (
            (1 5 6 2)
        );
    }
    freestream
    {
        type symmetry;
        faces
        (
       //     (1 5 6 2)
            (4 7 6 5)
            (3 2 6 7)
            (0 4 5 1)
        );
    }
    ground
    {
        type wall;
        faces
        (
            (0 1 2 3)
        );
    }
);

